package add_command

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/binds/cli.go, and what it
// returns is one entry of sandbox.Commands.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	command := api.NewCommand()

	command.Name = "add_command"
	command.Identifiers = []string{"add-command"}
	command.Category = "Cli System"
	command.Help = "Scaffold a new command package in the project"
	command.LongDescription = "Creates sandbox/internal/commands/<name>/ with a hand-written entries.yaml\nand a stub handler.go, then runs build so new.go and the dispatch pick it up.\nRefuses to overwrite an existing command."
	command.Examples = []string{"add-command my-feature", "add-command my-feature --path ./my-project"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "help",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "one-line help text for the new command",
			Examples:    []string{"add-command my-feature --help \"does the thing\" --category Misc"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--help"},
		},
		{
			Id:          "category",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the category the new command is grouped under in help output",
			Examples:    []string{"add-command my-feature --help \"does the thing\" --category Misc"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--category"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"add-command my-feature --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{"add-command my-feature -q"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the name of the new command (e.g. my-feature)",
			Examples:    []string{"add-command my-feature"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func() int {
		return CommandHandler(sandbox, command)
	}

	return command
}
